import { assets, defaults } from './assets.mjs';
const OWNER_EMAIL='nagendra@headrun.com';
const categories=['Hatchback','Sedan','SUV','Luxury','MPV'];
const statuses=['active','hidden','maintenance'];
class ApiError extends Error {constructor(status,message){super(message);this.status=status;}}
const json=(data,status=200,headers={})=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...headers}});
const dbFor=env=>{if(!env.DB)throw new ApiError(503,'Fleet storage is temporarily unavailable. Please try again.');return env.DB;};
const carFrom=row=>({...JSON.parse(row.data),id:row.id,version:row.version,updatedAt:row.updated_at});
async function body(request){if(Number(request.headers.get('content-length')||0)>30000)throw new ApiError(413,'Too much data.');let data;try{const text=await request.text();if(text.length>30000)throw new ApiError(413,'Too much data.');data=JSON.parse(text);}catch(e){if(e instanceof ApiError)throw e;throw new ApiError(400,'Invalid request data.');}return data;}
function text(value,label,max=100){if(typeof value!=='string'||!value.trim()||value.trim().length>max)throw new ApiError(400,`${label} is required (maximum ${max} characters).`);return value.trim();}
function safeUrl(value){if(!value)return '';if(typeof value!=='string'||value.length>2000)throw new ApiError(400,'Image URL is too long.');if(/^\/media\/[a-z0-9-]+\.(jpg|png|webp)$/.test(value))return value;let u;try{u=new URL(value);}catch{throw new ApiError(400,'Use a valid HTTPS image URL.');}if(u.protocol!=='https:'||u.username||u.password)throw new ApiError(400,'Use an HTTPS image URL.');return u.href;}
function price(value,label){if(value===''||value==null)return null;if(!Number.isSafeInteger(value)||value<0||value>10000000)throw new ApiError(400,`${label} must be a whole rupee amount between 0 and 10,000,000.`);return value;}
function owner(request){const email=request.headers.get('oai-authenticated-user-email');if(!email)throw new ApiError(401,'Sign in with the GoRide owner account to continue.');if(email.toLowerCase()!==OWNER_EMAIL)throw new ApiError(403,'Only the GoRide owner can manage this dashboard.');if(!['GET','HEAD'].includes(request.method)){const origin=request.headers.get('origin');if(origin&&origin!==new URL(request.url).origin)throw new ApiError(403,'Please save from the GoRide dashboard.');if(request.headers.get('sec-fetch-site')==='cross-site')throw new ApiError(403,'Cross-site changes are not allowed.');}return email;}
async function initialized(db){return !!await db.prepare('SELECT value FROM settings WHERE key = ?').bind('initialized').first();}
async function initialize(db){if(await initialized(db))return;const now=new Date().toISOString();await db.batch([...defaults.locations.map(l=>db.prepare('INSERT OR IGNORE INTO locations (id,name,enabled,version) VALUES (?,?,?,1)').bind(l.id,l.name,1)),...defaults.cars.map(c=>db.prepare('INSERT OR IGNORE INTO cars (id,data,version,updated_at) VALUES (?,?,1,?)').bind(c.id,JSON.stringify(c),now)),db.prepare('INSERT OR IGNORE INTO settings (key,value) VALUES (?,?)').bind('initialized','yes')]);}
async function readAll(db){if(!await initialized(db))return {...defaults,initialized:false};const [cars,locations]=await Promise.all([db.prepare('SELECT * FROM cars ORDER BY updated_at DESC,id').all(),db.prepare('SELECT * FROM locations ORDER BY name').all()]);return {cars:cars.results.map(carFrom),locations:locations.results.map(l=>({...l,enabled:!!l.enabled})),initialized:true};}
async function validateCar(input,db){if(!input||typeof input!=='object')throw new ApiError(400,'Invalid car.');const car={name:text(input.name,'Car name'),category:input.category,seats:input.seats,status:input.status,selfEnabled:input.selfEnabled,driverEnabled:input.driverEnabled,selfRate:price(input.selfRate,'Self-drive rate'),driverRate:price(input.driverRate,'Chauffeur rate'),deposit:price(input.deposit,'Deposit'),image:safeUrl(input.image),imageCredit:typeof input.imageCredit==='string'?input.imageCredit.trim().slice(0,200):'',imageSource:safeUrl(input.imageSource),imageLicense:typeof input.imageLicense==='string'?input.imageLicense.trim().slice(0,60):'',locationIds:input.locationIds,notes:typeof input.notes==='string'?input.notes.trim().slice(0,1000):''};if(!categories.includes(car.category)||!statuses.includes(car.status)||!Number.isInteger(car.seats)||car.seats<2||car.seats>20||typeof car.selfEnabled!=='boolean'||typeof car.driverEnabled!=='boolean'||(!car.selfEnabled&&!car.driverEnabled))throw new ApiError(400,'Choose a valid category, seats, status and at least one rental type.');if(!Array.isArray(car.locationIds)||!car.locationIds.length||car.locationIds.length>100||car.locationIds.some(id=>typeof id!=='string'))throw new ApiError(400,'Choose at least one location.');const known=await db.prepare('SELECT id FROM locations').all();if(car.locationIds.some(id=>!known.results.some(l=>l.id===id)))throw new ApiError(400,'A selected location no longer exists. Refresh and try again.');car.locationIds=[...new Set(car.locationIds)];return car;}
async function upload(request,env){if(!env.BUCKET)throw new ApiError(503,'Photo storage is temporarily unavailable.');const type=request.headers.get('content-type');if(!['image/jpeg','image/png','image/webp'].includes(type))throw new ApiError(400,'Choose a JPG, PNG or WebP photo.');if(Number(request.headers.get('content-length')||0)>8*1024*1024)throw new ApiError(413,'Photo must be smaller than 8 MB.');const reader=request.body?.getReader();if(!reader)throw new ApiError(400,'Choose a photo.');const chunks=[];let total=0;while(true){const {done,value}=await reader.read();if(done)break;total+=value.byteLength;if(total>8*1024*1024){await reader.cancel();throw new ApiError(413,'Photo must be smaller than 8 MB.');}chunks.push(value);}const bytes=new Uint8Array(total);let offset=0;for(const part of chunks){bytes.set(part,offset);offset+=part.length;}const isJpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;const isPng=bytes.length>8&&[137,80,78,71,13,10,26,10].every((n,i)=>bytes[i]===n);const isWebp=new TextDecoder().decode(bytes.slice(0,4))==='RIFF'&&new TextDecoder().decode(bytes.slice(8,12))==='WEBP';if(!(type==='image/jpeg'&&isJpg||type==='image/png'&&isPng||type==='image/webp'&&isWebp))throw new ApiError(400,'The file does not match its image type.');const ext=type==='image/jpeg'?'jpg':type==='image/png'?'png':'webp';const key=`${crypto.randomUUID()}.${ext}`;await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:type}});return json({url:`/media/${key}`},201);}
async function route(request,env){const url=new URL(request.url),path=url.pathname;
if(path==='/api/catalog'&&request.method==='OPTIONS')return new Response(null,{status:204,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, OPTIONS'}});
if(path==='/api/catalog'&&request.method==='GET'){const data=await readAll(dbFor(env));const locations=data.locations.filter(l=>l.enabled);const enabledIds=new Set(locations.map(l=>l.id));const cars=data.cars.filter(c=>c.status==='active'&&c.locationIds.some(id=>enabledIds.has(id))).map(c=>({...c,locationIds:c.locationIds.filter(id=>enabledIds.has(id))}));return json({cars,locations,initialized:data.initialized},200,{'Access-Control-Allow-Origin':'*'});}
if(path.startsWith('/media/')&&['GET','HEAD'].includes(request.method)){const key=path.slice(7);if(!/^[a-z0-9-]+\.(jpg|png|webp)$/.test(key))throw new ApiError(404,'Photo not found.');if(!env.BUCKET)throw new ApiError(503,'Photo storage unavailable.');const file=await env.BUCKET.get(key);if(!file)throw new ApiError(404,'Photo not found.');return new Response(request.method==='HEAD'?null:file.body,{headers:{'Content-Type':file.httpMetadata?.contentType||'application/octet-stream','Cache-Control':'public,max-age=31536000,immutable','X-Content-Type-Options':'nosniff'}});}
if(path.startsWith('/api/admin/')){const email=owner(request),db=dbFor(env);
if(path==='/api/admin/session'&&request.method==='GET')return json({email});
if(path==='/api/admin/initialize'&&request.method==='POST'){await initialize(db);return json(await readAll(db));}
if(path==='/api/admin/catalog'&&request.method==='GET')return json(await readAll(db));
if(path==='/api/admin/photos'&&request.method==='POST')return upload(request,env);
if(path==='/api/admin/cars'&&request.method==='POST'){await initialize(db);const input=await body(request),car=await validateCar(input,db),id=crypto.randomUUID(),now=new Date().toISOString();await db.prepare('INSERT INTO cars (id,data,version,updated_at) VALUES (?,?,1,?)').bind(id,JSON.stringify(car),now).run();return json({...car,id,version:1,updatedAt:now},201);}
const carMatch=path.match(/^\/api\/admin\/cars\/([a-z0-9-]+)$/);
if(carMatch&&request.method==='PUT'){const input=await body(request),car=await validateCar(input,db);if(!Number.isInteger(input.version)||input.version<1)throw new ApiError(400,'Refresh this car before saving.');const now=new Date().toISOString();const result=await db.prepare('UPDATE cars SET data = ?,version = version + 1,updated_at = ? WHERE id = ? AND version = ?').bind(JSON.stringify(car),now,carMatch[1],input.version).run();if(!result.meta.changes)throw new ApiError(409,'This car changed in another tab. Your draft is kept. Close it and refresh before editing again.');return json({...car,id:carMatch[1],version:input.version+1,updatedAt:now});}
if(path==='/api/admin/locations'&&request.method==='POST'){await initialize(db);const input=await body(request),name=text(input.name,'Location',80);const duplicate=await db.prepare('SELECT id FROM locations WHERE lower(name) = lower(?)').bind(name).first();if(duplicate)throw new ApiError(409,'That location already exists.');const id=crypto.randomUUID();await db.prepare('INSERT INTO locations (id,name,enabled,version) VALUES (?,?,1,1)').bind(id,name).run();return json({id,name,enabled:true,version:1},201);}
const locationMatch=path.match(/^\/api\/admin\/locations\/([a-z0-9-]+)$/);
if(locationMatch&&request.method==='PUT'){const input=await body(request),name=text(input.name,'Location',80);if(typeof input.enabled!=='boolean'||!Number.isInteger(input.version))throw new ApiError(400,'Invalid location status.');const duplicate=await db.prepare('SELECT id FROM locations WHERE lower(name) = lower(?) AND id != ?').bind(name,locationMatch[1]).first();if(duplicate)throw new ApiError(409,'That location already exists.');const result=await db.prepare('UPDATE locations SET name = ?,enabled = ?,version = version + 1 WHERE id = ? AND version = ?').bind(name,input.enabled?1:0,locationMatch[1],input.version).run();if(!result.meta.changes)throw new ApiError(409,'This location changed in another tab. Refresh and try again.');return json({id:locationMatch[1],name,enabled:input.enabled,version:input.version+1});}
throw new ApiError(404,'This action is not available.');}
if(path==='/admin'||path==='/admin/'||path==='/admin.html'){try{owner(request);}catch(error){if(error.status===401)return Response.redirect(url.origin+'/signin-with-chatgpt?return_to=%2Fadmin',302);throw error;}}
const asset=assets[path==='/admin'||path==='/admin/'?'/admin.html':path==='/'?'/index.html':path];if(asset&&['GET','HEAD'].includes(request.method))return new Response(request.method==='HEAD'?null:asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' https: blob: data:; connect-src 'self'; frame-ancestors 'self' https://*.chatgpt.com https://chatgpt.com; base-uri 'self'; form-action 'self'"}});
throw new ApiError(404,'Page not found.');}
export default {async fetch(request,env){try{return await route(request,env);}catch(e){if(!(e instanceof ApiError))console.error('GoRide storage operation failed:',e.message);return json({error:e instanceof ApiError?e.message:'Could not complete the request. Your changes have not been confirmed. Please retry.'},e instanceof ApiError?e.status:503);}}};
